The filter chain protects the HTTP boundary. The method annotation protects calls that pass through the Spring method-security proxy. If this application also used `@Secured`, the configuration would need `@EnableMethodSecurity(securedEnabled = true)`.

@Configuration
@EnableWebSecurity
public class SecurityConfig {

    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        http
            .authorizeHttpRequests(auth -> auth
                .requestMatchers("/api/public/**").permitAll()  // No auth needed
                .requestMatchers("/api/admin/**").hasRole("ADMIN")  // ADMIN role required
                .anyRequest().authenticated()  // Everything else needs authentication
            )
            .httpBasic(Customizer.withDefaults());  // Enable HTTP Basic authentication
        return http.build();
    }

    @Bean
    public UserDetailsService userDetailsService() {
        var admin = User.withUsername("admin")
            .password("{noop}admin123")  // {noop} = no password encoding (dev only)
            .roles("ADMIN")
            .build();
        return new InMemoryUserDetailsManager(admin);  // In-memory user for testing
    }
}

@Configuration
@EnableMethodSecurity
class RestSecurityConfig {

    @Bean
    SecurityFilterChain apiFilterChain(
            HttpSecurity http,
            AuthenticationEntryPoint entryPoint,
            AccessDeniedHandler deniedHandler) throws Exception {
        http
            .securityMatcher("/api/**")
            .sessionManagement(session -> session
                .sessionCreationPolicy(SessionCreationPolicy.STATELESS))
            // Appropriate for this chain only because it accepts an explicit bearer header.
            .csrf(csrf -> csrf.disable())
            .authorizeHttpRequests(auth -> auth
                .requestMatchers("/api/public/**").permitAll()
                .requestMatchers("/api/admin/**").hasRole("ADMIN")
                .anyRequest().authenticated())
            .oauth2ResourceServer(oauth2 -> oauth2
                .jwt(Customizer.withDefaults())
                .authenticationEntryPoint(entryPoint))
            .exceptionHandling(ex -> ex
                .accessDeniedHandler(deniedHandler));
        return http.build();
    }
}

