@Component
class RestAuthenticationEntryPoint implements AuthenticationEntryPoint {
    private final ObjectMapper json;

    RestAuthenticationEntryPoint(ObjectMapper json) {
        this.json = json;
    }

    @Override
    public void commence(HttpServletRequest request, HttpServletResponse response,
                         AuthenticationException failure) throws IOException {
        response.setStatus(HttpServletResponse.SC_UNAUTHORIZED);
        response.setContentType(MediaType.APPLICATION_JSON_VALUE);
        json.writeValue(response.getOutputStream(),
            new ApiError(401, "authentication_required", request.getRequestURI()));
    }
}

@Component
class RestAccessDeniedHandler implements AccessDeniedHandler {
    private final ObjectMapper json;

    RestAccessDeniedHandler(ObjectMapper json) {
        this.json = json;
    }

    @Override
    public void handle(HttpServletRequest request, HttpServletResponse response,
                       AccessDeniedException failure) throws IOException {
        response.setStatus(HttpServletResponse.SC_FORBIDDEN);
        response.setContentType(MediaType.APPLICATION_JSON_VALUE);
        json.writeValue(response.getOutputStream(),
            new ApiError(403, "access_denied", request.getRequestURI()));
    }
}
